with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, 'アルノルフィーニ夫妻像', 'ヤン・ファン・エイク', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Van_Eyck_-_Arnolfini_Portrait.jpg/960px-Van_Eyck_-_Arnolfini_Portrait.jpg', '1434年、フランドルの画家ヤン・ファン・エイクが樫の板に油彩で描いた全身の二重肖像で、ロンドンのナショナル・ギャラリーが所蔵しています。ブルッヘに住んだイタリア商人ジョヴァンニ・アルノルフィーニと妻を描いたと考えられています。見どころは奥の壁の凸面鏡で、夫妻が向き合う戸口のすぐ内側に立つ二人の人物が映り込み、画面の空間を広げています。鏡の上には「ヤン・ファン・エイクここにありき 1434」という署名が書かれています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Van_Eyck_-_Arnolfini_Portrait.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 1
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('ラファエル・ザルカ、日本初の本格個展を京都で', '京都市京セラ美術館で2027年2月から、フランスの作家ラファエル・ザルカの特別展が開かれると京都市が発表しました。', '京都市は10月16日、京都市京セラ美術館で特別展「ラファエル・ザルカ：幾何学、時間、スケートボード」を開催すると発表しました。パリを拠点に活動するザルカ（1977–）の日本で初めての本格的な個展です。ザルカは幾何学や数学、彫刻、建築、スケートボードなどの領域を横断し、形態と空間、運動と時間の関係を探究してきました。本展では代表作に加え、2026年4月から7月にかけての京都滞在で制作される新作も展示する予定です。会期は2027年2月6日から5月5日まで、会場は新館 東山キューブです。', '', '展覧会', 'https://www.city.kyoto.lg.jp/bunshi/page/0000359144.html',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('東京都美術館、開館100年をたどるアーカイブ展', '東京都美術館が開館100周年を記念し、館のあゆみを資料で振り返る展覧会を11月19日から無料で開きます。', '東京都歴史文化財団は10月19日、「東京都美術館開館100周年記念 はじまりをひらく 東京都美術館の100年」を11月19日から2027年1月11日まで開催すると発表しました。東京都美術館は1926年、石炭業で財を成した佐藤慶太郎が建設資金として100万円を寄付したことで、東京府美術館として上野に開館しました。本展は5つの章とプロローグ、エピローグで100年の歴史を紹介し、展覧会の記録や写真、建築図面などのアーカイブズ資料に加え、一般から募集した同館の写真もあわせて展示します。会場はギャラリーB、観覧は無料です。', '', '美術館', 'https://prtimes.jp/main/html/rd/p/000001162.000038211.html',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('ユドニー（若いアメリカ娘、ダンス）', 'Udnie', 'フランシス・ピカビア', 'Francis Picabia',
        1913,
        (select slug from public.art_movements where slug = 'cubism'),
        'ポンピドゥー・センター（国立近代美術館）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/Francis_Picabia%2C_1913%2C_Udnie_%28Young_American_Girl%2C_The_Dance%29%2C_oil_on_canvas%2C_290_x_300_cm%2C_Mus%C3%A9e_National_d%E2%80%99Art_Moderne%2C_Centre_Georges_Pompidou%2C_Paris..jpg/960px-Francis_Picabia%2C_1913%2C_Udnie_%28Young_American_Girl%2C_The_Dance%29%2C_oil_on_canvas%2C_290_x_300_cm%2C_Mus%C3%A9e_National_d%E2%80%99Art_Moderne%2C_Centre_Georges_Pompidou%2C_Paris..jpg', '1913年、アーモリー・ショーに参加するためアメリカへ渡る船上で、ダンサーのスタシア・ナピエルコフスカの踊りを見たことから生まれたとされる大作です。踊る身体は、金属のような光沢をもつ色面の渦へと解体され、人の姿はもう読み取れません。前年にパリで見た未来派の運動表現や、デュシャンの機械的な形の影響がうかがえ、詩人アポリネールが名づけたオルフィスムとも結びつけられます。キュビスムが分解した形を、ピカビアは音楽のような純粋な色と動きへ押し進め、このあと機械をモチーフにしたダダの作品へ向かいました。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Francis_Picabia,_1913,_Udnie_(Young_American_Girl,_The_Dance),_oil_on_canvas,_290_x_300_cm,_Musée_National_d’Art_Moderne,_Centre_Georges_Pompidou,_Paris..jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('死の海（トーテス・メーア）', 'Totes Meer', 'ポール・ナッシュ', 'Paul Nash',
        1941,
        (select slug from public.art_movements where slug = 'surrealism'),
        'テート', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/Totes_Meer_%28Dead_Sea%29_1940-1_Paul_Nash.jpg/960px-Totes_Meer_%28Dead_Sea%29_1940-1_Paul_Nash.jpg', '第二次世界大戦中、戦争画家として働いていたナッシュが、オックスフォード近郊カウリーの航空機の残骸置き場で描いたスケッチや写真をもとに仕上げた作品です。月明かりの下、撃墜されたドイツ空軍機の翼や胴体が積み重なり、凍りついた波が打ち寄せる海のように見えます。題名はドイツ語で「死の海」の意味です。1936年の国際シュルレアリスム展にも参加したナッシュは、イギリスの風景の中に夢のような不穏さを見いだしました。現実の光景を別のものに見立てるシュルレアリスムの方法を、戦争の記録に生かした一枚です。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Totes_Meer_(Dead_Sea)_1940-1_Paul_Nash.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('サルダナパールの死', 'The Death of Sardanapalus', 'ウジェーヌ・ドラクロワ', 'Eugène Delacroix',
        1827,
        (select slug from public.art_movements where slug = 'romanticism'),
        'ルーヴル美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/La_Mort_de_Sardanapale_-_Eug%C3%A8ne_Delacroix_-_Mus%C3%A9e_du_Louvre_Peintures_RF_2346.jpg/960px-La_Mort_de_Sardanapale_-_Eug%C3%A8ne_Delacroix_-_Mus%C3%A9e_du_Louvre_Peintures_RF_2346.jpg', '古代ギリシャの歴史家ディオドロスが伝えるアッシリア王サルダナパールの物語に取材し、バイロンの戯曲『サルダナパール』（1821年）に着想を得た大作です。死を前にした王が、人も贅沢な品々もすべて道連れに滅ぼそうとする場面を、縦約4メートル、横約5メートルの画面に、鮮やかな暖色と幅の広い筆づかいで描いています。1827年のサロンでは賛否が大きく分かれました。ダヴィッド《ホラティウス兄弟の誓い》のような新古典主義の英雄像とは正反対の主人公を、色彩と激情で描いたロマン主義の代表作です。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:La_Mort_de_Sardanapale_-_Eugène_Delacroix_-_Musée_du_Louvre_Peintures_RF_2346.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('牧場の聖母', 'Madonna of the Meadow', 'ラファエロ・サンツィオ', 'Raphael',
        1506,
        (select slug from public.art_movements where slug = 'renaissance'),
        'ウィーン美術史美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Raphael_-_Madonna_in_the_Meadow_-_Google_Art_Project.jpg/960px-Raphael_-_Madonna_in_the_Meadow_-_Google_Art_Project.jpg', '1504〜1505年にフィレンツェへ移ったラファエロが、23歳のころ、数か月のうちに描いた板絵の油彩画です。穏やかな草原に、聖母マリアと幼いキリスト、幼い洗礼者ヨハネが、互いの視線で結ばれたピラミッド形に配置されています。赤い衣に金の縁取りの青いマントをまとった聖母は、ヨハネの差し出す小さな十字架に手を伸ばす幼子をそっと支えます。同じころフィレンツェにいたレオナルドに倣い、人物をピラミッド形にまとめる手法を取り入れつつ、明るく柔らかな調和にまとめた盛期ルネサンスの聖母子像で、長くウィーンのベルヴェデーレに置かれていました。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Raphael_-_Madonna_in_the_Meadow_-_Google_Art_Project.jpg')
