insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('円山応挙', 'Maruyama Ōkyo', '応挙',
        1733, 1795, 'japan', array[]::text[],
        '写生を重んじた画風で「円山派」を開いた、江戸時代中期から後期の京都の絵師。', '丹波国穴太村（現在の京都府亀岡市）の農家に生まれました。10代のうちに京へ出て、狩野探幽の流れをくむ鶴沢派の石田幽汀に学びます。20代には玩具商に勤め、西洋の遠近法を応用した「眼鏡絵」を手がけました。

1766年から「応挙」と名乗り、三井寺円満院の祐常や豪商の三井家などの支援を受けました。いつも懐に写生帖を入れて動植物を写したといわれ、写生を基礎にしながら伝統的な画題を装飾性ゆたかな大画面にまとめたのが特色です。

代表作に国宝《雪松図屏風》や兵庫・大乗寺の障壁画があります。呉春や長沢芦雪らの弟子に受け継がれた「円山・四条派」は、近現代の京都画壇の源流となりました。諸説ありますが、「足のない幽霊」を描き始めた画家ともいわれています。', 'https://ja.wikipedia.org/wiki/%E5%86%86%E5%B1%B1%E5%BF%9C%E6%8C%99')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ウンベルト・ボッチョーニ', 'Umberto Boccioni', 'ボッチョーニ',
        1882, 1916, 'west', array['futurism']::text[],
        '未来派の中心メンバーとして、絵画と彫刻で運動と速度を表したイタリアの芸術家。', '1882年、イタリア南部のレッジョ・ディ・カラブリアに生まれ、幼年期をフォルリで過ごしました。ローマの美術アカデミーで学び、1906年にはパリで印象派やポスト印象派の作風に触れます。1907年にミラノへ移り、詩人マリネッティや色彩分離派の画家たちと交流しました。

1910年、カッラ、ルッソロ、バッラ、セヴェリーニとともに「未来派画家宣言」を発表し、過去の伝統から離れて、動き続ける近代社会を描くことを目指しました。《都市は立ち上がる》では、建設の進む都市の熱気を、人と馬が渦を巻く画面で表しました。

彫刻《空間における連続性の唯一の形態》はイタリアの20セント・ユーロ硬貨の図柄にもなっています。第一次世界大戦に従軍中の1916年、訓練中の落馬事故により33歳で亡くなりました。', 'https://ja.wikipedia.org/wiki/%E3%82%A6%E3%83%B3%E3%83%99%E3%83%AB%E3%83%88%E3%83%BB%E3%83%9C%E3%83%83%E3%83%81%E3%83%A7%E3%83%BC%E3%83%8B')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('フランシス・ピカビア', 'Francis Picabia', 'ピカビア',
        1879, 1953, 'west', array['cubism', 'dada']::text[],
        '印象派風の風景からキュビスム、ダダへと作風を次々に変えたフランスの画家・詩人。', '1879年、パリでキューバ公使館員の父とフランス人の母のもとに生まれました。国立高等装飾美術学校で学んだのち、印象派風の風景画で画家として歩み始め、1905年にはパリで初の個展を開いています。

1909年ごろ、妻ガブリエル・ビュッフェの勧めで抽象画に転じ、ピュトー・グループやセクション・ドール展に加わりました。1913年にはニューヨークのアーモリー・ショーに出品し、1915年ごろからは機械の部品や図面をモチーフにした作品を描きます。ニューヨーク・ダダに加わり、1918年にはスイスでチューリッヒのダダのグループに参加しました。

その後シュルレアリスムにも近づきますが、やがて離れ、生涯を通じて作風をめまぐるしく変えたことで知られます。第二次世界大戦中はスイスで過ごし、戦後はパリに戻りました。', 'https://ja.wikipedia.org/wiki/%E3%83%95%E3%83%A9%E3%83%B3%E3%82%B7%E3%82%B9%E3%83%BB%E3%83%94%E3%82%AB%E3%83%93%E3%82%A2')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
